$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
. (Join-Path $PSScriptRoot '../character-finish-scope.ps1')
. (Join-Path $PSScriptRoot '../prepare-font-only-preview.ps1')
$Repo=(Resolve-Path -LiteralPath (Join-Path $PSScriptRoot '../..')).Path
$Root=Join-Path ([IO.Path]::GetTempPath()) ('font-only-fixture-'+[guid]::NewGuid().ToString('N'))
$Folder=Join-Path $Root 'screenshots';New-Item -ItemType Directory -Path $Folder -Force|Out-Null
$Rev='a'*40;$Fp='b'*64;$Packed='c'*64
$Png720=[Convert]::FromBase64String('')
$Png640=[Convert]::FromBase64String('')
function Reject([scriptblock]$Action){$Rejected=$false;try{& $Action|Out-Null}catch{$Rejected=$true};if(-not $Rejected){throw 'Invalid font-only evidence accepted.'}}
function Fixture{
    $Rows=@(foreach($Width in @(720,640)){foreach($Screen in @('town','conversation','merge','quest','book')){
        $Height=if($Width -eq 720){1480}else{1072};$Name=$Screen+'-'+$Width+'x'+$Height+'.png';$File=Join-Path $Folder $Name
        [IO.File]::WriteAllBytes($File,$(if($Width -eq 720){$Png720}else{$Png640}))
        @{file=$Name;screen=$Screen;width=$Width;height=$Height;sha256=(Get-FileHash -LiteralPath $File -Algorithm SHA256).Hash.ToLowerInvariant();state_sha256=('d'*64);geometry_sha256=('e'*64);fonts=@(@{name='Coins value';font='fixture';resource='UIFontAccent';style='Bold';reason='Hachi primary';hachi_fits=$true;size=13})}
    }})
    $P=@{kind='hachi-font-only-native';source_revision=$Rev;product_fingerprint=$Fp;packed_resource_sha256=$Packed;output_directory=$Folder;native_unity=$true;disk_verified=$true;visual_approved=$false;pixel_verified=$false;image_count=10;images=$Rows}
    $P|ConvertTo-Json -Depth 9|Set-Content -LiteralPath (Join-Path $Folder 'font-only-native.json') -Encoding UTF8
    [IO.File]::WriteAllText((Join-Path $Folder 'font-only.html'),'<!doctype html>'+($Rows.file -join ' '));return $P
}
try{
    $null=Fixture;if(@(Assert-FontOnlyArtifacts $Root $Rev $Fp $Packed).Count -ne 12){throw 'Ten PNGs plus JSON/HTML required.'}
    foreach($Case in @('missing','zero','json','html','sha','output','count','fonts','font','false-fallback','accepted','png-size','viewer')){
        $P=Fixture
        switch($Case){
            missing {Remove-Item -LiteralPath (Join-Path $Folder $P.images[0].file)}
            zero {Get-ChildItem -LiteralPath $Folder -File|Remove-Item -Force}
            json {Remove-Item -LiteralPath (Join-Path $Folder 'font-only-native.json')}
            html {Remove-Item -LiteralPath (Join-Path $Folder 'font-only.html')}
            sha {$P.images[0].sha256=('f'*64)}
            output {$P.output_directory=Join-Path $Root 'wrong'}
            count {$P.image_count=0}
            fonts {$P.images[0].fonts=@()}
            font {$P.images[0].fonts[0].resource='UIFontStory'}
            false-fallback {$P.images[0].fonts[0].resource='UIFontReadingBold'}
            accepted {$P.visual_approved=$true}
            png-size {[IO.File]::WriteAllBytes((Join-Path $Folder $P.images[0].file),$Png640);$P.images[0].sha256=(Get-FileHash -LiteralPath (Join-Path $Folder $P.images[0].file) -Algorithm SHA256).Hash.ToLowerInvariant()}
            viewer {[IO.File]::WriteAllText((Join-Path $Folder 'font-only.html'),'<!doctype html>no images')}
        }
        if($Case -notin @('zero','json')){$P|ConvertTo-Json -Depth 9|Set-Content -LiteralPath (Join-Path $Folder 'font-only-native.json') -Encoding UTF8}
        Reject {Assert-FontOnlyArtifacts $Root $Rev $Fp $Packed}
    }
    $null=Fixture;$Record=[ordered]@{source_unchanged=$true;error='';capture_verified=$false;image_count=0;artifacts=@()};Confirm-FontOnlyCapture $Record $Root $Rev $Fp $Packed
    if(-not $Record.capture_verified){throw 'Complete files were not verified.'}
    $Zip=Write-FontOnlyReviewPackage $Record $Root $Rev $Fp $Packed;if(-not(Test-Path -LiteralPath $Zip -PathType Leaf)){throw 'Share ZIP missing.'}
    Remove-Item -LiteralPath (Join-Path $Folder 'font-only.html');Reject {Confirm-FontOnlyCapture $Record $Root $Rev $Fp $Packed};if($Record.capture_verified -or $Record.image_count -ne 0){throw 'Postprocessing loss kept success.'}
    $A=@(Get-FontOnlyArguments $Repo $Root $Rev $Fp $Packed);$ArgsText=$A -join ' '
    if($ArgsText -notmatch '-mofumachiFontOnly' -or $ArgsText -notmatch 'ScopedFontsFit' -or $ArgsText -notmatch 'StoryTypographyTests' -or $ArgsText -match 'MergeRewardCaptureTests|FontComparison|ReceiptShows|executeMethod|full-playmode'){throw 'Font-only capture filter expanded.'}
    $Relative='References/VisualLock/font-only-2026-11-04.json';$Good=[IO.File]::ReadAllText((Join-Path $Repo $Relative));$C=$Good|ConvertFrom-Json
    foreach($Row in @($C.parents)+@($C.overrides)+@($C.additions)){$Target=Join-Path $Root $Row.path;New-Item -ItemType Directory -Path (Split-Path -Parent $Target) -Force|Out-Null;Copy-Item -LiteralPath (Join-Path $Repo $Row.path) -Destination $Target}
    $Manifest=Join-Path $Root $Relative;[IO.File]::WriteAllText($Manifest,$Good);$null=Read-FontOnlyAmendment $Root
    foreach($Case in @('core','art','duplicate','before','baseline','accepted','helper','hash','parent')){
        $Bad=$Good|ConvertFrom-Json
        switch($Case){
            core {$Bad.overrides[0].path='Assets/Mofumachi/Core/GameState.cs'}
            art {$Bad.overrides[0].path='Assets/Mofumachi/Resources/Mofumachi/TitleLogo.png'}
            duplicate {$Bad.overrides[1]=$Bad.overrides[0]}
            before {$Bad.overrides[0].before_sha256=('f'*64)}
            baseline {$Bad.baseline_revision=('f'*40)}
            accepted {$Bad.native_verified=$true}
            helper {$Bad.additions=@()}
            hash {$Bad.overrides[0].sha256=('f'*64)}
            parent {$Bad.parents[0].sha256=('f'*64)}
        }
        [IO.File]::WriteAllText($Manifest,($Bad|ConvertTo-Json -Depth 9));Reject {Read-FontOnlyAmendment $Root}
    }
}finally{if(Test-Path -LiteralPath $Root){Remove-Item -LiteralPath $Root -Recurse -Force}}
Write-Host 'Font-only artifact count/hash/PNG/roles/cleanup, exact scope and two-test capture arguments passed. Synthetic fixtures, not Unity screenshots.'
